provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_vpc" "my_api_vpc" {
  cidr_block = "10.0.0.0/16"
  instance_tenancy = "default"
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "my_api_vpc"
  }
}

resource "aws_subnet" "my_api_subnet" {
  vpc_id = aws_vpc.my_api_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true

  tags = {
    Name = "my_api_subnet"
  }
}

resource "aws_launch_configuration" "my_api_lc" {
  image_id = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t3.micro"
  security_groups = [aws_security_group.my_api_sg.id]
  user_data = <<-EOF
    #!/bin/bash
    echo "Hello, World!" > /var/www/html/index.html
    EOF

  associate_public_ip_address = true
}

resource "aws_security_group" "my_api_sg" {
  name = "my_api_sg"
  vpc_id = aws_vpc.my_api_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_autoscaling_group" "my_api_asg" {
  name               = "my_api_asg"
  launch_configuration = aws_launch_configuration.my_api_lc.id
  min_size           = 1
  max_size           = 3
  desired_capacity   = 2

  health_check_type = "EC2"
  health_check_grace_period = 300

  load_balancers = [aws_elastic_load_balancer.my_api_elb.name]

  tags = {
    Name = "my_api_asg"
  }
}

resource "aws_elastic_load_balancer" "my_api_elb" {
  name               = "my_api_elb"
  subnets            = [aws_subnet.my_api_subnet.id]
  security_groups     = [aws_security_group.my_api_sg.id]
  internal           = false
  cross_zone_load_balancing = true

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 30
    interval            = 30
  }

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port            = 80
    lb_protocol        = "http"
  }
}

resource "aws_elastic_beanstalk_application" "my_api_app" {
  name = "my_api_app"
}

resource "aws_elastic_beanstalk_environment" "my_api_env" {
  name                = "my_api_env"
  application         = aws_elastic_beanstalk_application.my_api_app.name
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"
  environment_type    = "LoadBalanced"
  instance_type       = "t3.micro"
  vpc_id              = aws_vpc.my_api_vpc.id
  subnet_ids          = [aws_subnet.my_api_subnet.id]
  security_groups     = [aws_security_group.my_api_sg.id]

  settings = [
    {
      namespace = "aws:autoscaling:asg"
