}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_sqs_queue" "batch_job_queue" {
  name = "batch_job_queue"
}

resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
}

resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.bucket
  key    = "examplebucket_object"
  source = "path/to/your/application.zip"
}

resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name = "batch_job_app"
}

resource "aws_elastic_beanstalk_environment" "batch_job_env" {
  application         = aws_elastic_beanstalk_application.batch_job_app.name
  name                = "batch_job_env"
  platform_arn        = "arn:aws:elasticbeanstalk:us-west-2::platform/Python 3.8 running on 64bit Amazon Linux 2"
  tier                = "Worker"
  version_label       = "version"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name
  environment_variables = {
    EB_ENVIRONMENT_NAME = "batch_job_env"
    EB_APPLICATION_NAME = "batch_job_app"
  }
}

resource "aws_lambda_function" "batch_job_lambda" {
  function_name = "batch_job_lambda"
  role           = aws_iam_role.eb_ec2_role.arn
  handler        = "index.handler"
  runtime        = "python3.8"
  code           = filebase64("path/to/your/application.zip")
}

resource "aws_cloudwatch_event_rule" "batch_job_event_rule" {
  name        = "batch_job_event_rule"
  schedule_expression = "rate(1 minute)"
}

resource "aws_cloudwatch_event_target" "batch_job_event_target" {
  arn       = aws_sqs_queue.batch_job_queue.arn
  rule      = aws_cloudwatch_event_rule.batch_job_event_rule.name
  target_id = "batch_job_target"
}
