  username = "admin"
  password = "securepassword123"
  db_subnet_group_name = "default"
  vpc_security_group_ids = [aws_security_group.staging_db_sg.id]
  skip_final_snapshot = true
}

resource "aws_security_group" "prod_db_sg" {
  name        = "prod_db_sg"
  description = "Security group for production database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "staging_db_sg" {
  name        = "staging_db_sg"
  description = "Security group for staging database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_elastic_beanstalk_application" "production_app" {
  name = "production-app"
}

resource "aws_elastic_beanstalk_application" "staging_app" {
  name = "staging-app"
}

resource "aws_elastic_beanstalk_environment" "production_env" {
  application = aws_elastic_beanstalk_application.production_app.name
  name        = "production-env"
  solution_stack_name = "64bit Amazon Linux 2015.03 v2.0.3 running Go 1.4"
  database_name = aws_db_instance.prod_db.db_name
  database_username = aws_db_instance.prod_db.username
  database_password = aws_db_instance.prod_db.password
