resource "aws_s3_bucket" "snapshot_bucket" {
  bucket = "my-db-snapshots"
  acl = "private"
  tags = {
    Name = "DBSnapshotsBucket"
  }
}

resource "aws_s3_bucket_object" "snapshot_object" {
  bucket = aws_s3_bucket.snapshot_bucket.bucket
  key = "${var.db_name}-snapshot-${timestamp()}.tar.gz"
  source = "path/to/your/database/snapshot.tar.gz"  # Replace with the actual path to your database snapshot
  etag = filemd5("path/to/your/database/snapshot.tar.gz")  # Replace with the actual ETag of your database snapshot
}

resource "aws_elasticbeanstalk_application" "eb_app" {
  name = "my-eb-app"
  description = "Elastic Beanstalk application for the database"
}

resource "aws_elasticbeanstalk_environment" "eb_env" {
  name = "my-eb-env"
  application = aws_elasticbeanstalk_application.eb_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"
  instance_profile = var.instance_profile_name
  database_name = var.db_name
  database_username = "admin"
  database_password = "securepassword123"
  database_host = aws_db_instance.rds_instance.endpoint
  database_port = aws_db_instance.rds_instance.port
  environment_variables = {
    DB_NAME = var.db_name
    DB_USER = "admin"
    DB_PASSWORD = "securepassword123"
    DB_HOST = aws_db_instance.rds_instance.endpoint
    DB_PORT = aws_db_instance.rds_instance.port
  }
  depends_on = [aws_db_instance.rds_instance]
}
