}

resource "aws_s3_bucket" "go_app_bucket" {
  bucket = "go-app-bucket-${var.environment}-${var.version}"
  acl    = "private"

  tags = {
    Name        = "Go App Bucket"
    Environment = var.environment
    Version     = var.version
  }
}

resource "aws_s3_object" "go_app_zip" {
  bucket = aws_s3_bucket.go_app_bucket.bucket
  key    = "go-app.zip"
  source = "path/to/go-app.zip"

  tags = {
    Name        = "Go App Zip"
    Environment = var.environment
    Version     = var.version
  }
}

resource "aws_elastic_beanstalk_application" "go_app" {
  name        = "go-app-${var.environment}-${var.version}"
  description = "Go App Application"

  appversion_lifecycle {
    service_role = aws_iam_role.beanstalk_service.arn
    max_count     = 128
    delete_source_from_s3 = true
  }
}

resource "aws_elastic_beanstalk_application_version" "go_app_version" {
  application = aws_elastic_beanstalk_application.go_app.name
  bucket      = aws_s3_bucket.go_app_bucket.bucket
  key         = aws_s3_object.go_app_zip.key
  name        = "go-app-version-${var.environment}-${var.version}"

  description = "Go App Version"
}

resource "aws_elastic_beanstalk_environment" "go_app_env" {
  application = aws_elastic_beanstalk_application.go_app.name
  name        = "go-app-env-${var.environment}-${var.version}"

  solution_stack_name = "64bit Amazon Linux 2015.09 v2.0.8 running Go 1.4"
  version_label      = aws_elastic_beanstalk_application_version.go_app_version.name
}
```

**Explanation**:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **IAM Role**: An IAM role `beanstalk-service-role` is created to allow Elastic Beanstalk to assume it.
- **S3 Bucket**: A private S3 bucket `go-app-bucket-${var.environment}-${var.version}` is created with a descriptive name and tags.
- **S3 Object**: A zip file `go-app.zip` is uploaded to the S3 bucket.
- **Elastic Beanstalk Application**: An application `go-app-${var.environment}-${var.version}` is created with a lifecycle policy that specifies the service role and deletion behavior.
- **Elastic Beanstalk Application Version**: An application version `go-app-version-${var.environment}-${var.version}` is created from the uploaded zip file.
- **Elastic Beanstalk Environment**: An environment `go-app-env-${var.environment}-${var.version}` is created using the specified solution stack and application version.

