    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# Create an S3 bucket for storing application versions
resource "aws_s3_bucket" "application_versions" {
  bucket = "tf-test-application-versions"
  acl    = "private"
}

# Upload the application code to the S3 bucket
resource "aws_s3_object" "application_code" {
  bucket = aws_s3_bucket.application_versions.id
  key    = "go-v1.zip"
  source = "go-v1.zip"
}

# Create an Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "web_app" {
  name        = "tf-test-web-app"
  description = "A web application"

  appversion_lifecycle {
    service_role = aws_iam_role.beanstalk_service.arn
    max_count             = 128
    delete_source_from_s3 = true
  }
}

# Create an Elastic Beanstalk configuration template
resource "aws_elastic_beanstalk_configuration_template" "web_app_config" {
  application = aws_elastic_beanstalk_application.web_app.name
  name        = "default"

  setting {
    name        = "InstanceType"
    namespace = "aws:ec2:instance"
    value       = "t3.micro"
  }
}

# Create an Elastic Beanstalk application version
resource "aws_elastic_beanstalk_application_version" "web_app_version" {
  application = aws_elastic_beanstalk_application.web_app.name
  bucket      = aws_s3_bucket.application_versions.id
  key         = aws_s3_object.application_code.key
  name        = "v1.0"
}

# Create an Auto Scaling group
resource "aws_autoscaling_group" "web_app_asg" {
  name_prefix = "web-app-asg-"
  max_size   = 3
  min_size   = 1

  launch_configuration = aws_launch_configuration.web_app_lc.name

  tags = {
    Name = "web-app-asg"
  }
}

# Create a Launch Configuration
resource "aws_launch_configuration" "web_app_lc" {
  name_prefix = "web-app-lc-"
  image_id      = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t3.micro"
}
