          Action = "ec2:DescribeVpcs"
          Resource = "*"
        },
      ]
    })
  }
}

resource "aws_codebuild_project" "example_codebuild_project" {
  name          = "example_codebuild_project"
  description   = "Example CodeBuild project with GitHub source and logs configuration"
  service_role  = aws_iam_role.example_iam_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = "my-codebuild-artifacts-bucket"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "SOME_KEY1"
      value = "SOME_VALUE1"
    }

    environment_variable {
      name  = "SOME_KEY2"
      value = "SOME_VALUE2"
      type  = "PARAMETER_STORE"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "my-codebuild-logs-group"
      stream_name = "my-codebuild-logs-stream"
    }

    s3_logs {
      status   = "ENABLED"
      location = "my-codebuild-logs-bucket"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/example.git"
    git_clone_depth = 1

    git_submodules_config {
      fetch_submodules = true
    }
  }

  source_version = "main"
}
