provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "lambda_policy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = "logs:CreateLogGroup"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Action = "logs:CreateLogStream"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Action = "logs:PutLogEvents"
          Effect = "Allow"
          Resource = "arn:aws:logs:*:*:*"
        },
        {
          Action = "s3:GetObject"
          Effect = "Allow"
          Resource = "arn:aws:s3:::your-bucket-name/*"
        },
      ]
    })
  }
}

resource "aws_lambda_function" "pizza_order_handler" {
  function_name = "pizza_order_handler"
  role          = aws_iam_role.lambda_execution_role.arn
  runtime       = "python3.8"
  handler       = "pizza_order_handler.handler"

  code {
    s3_bucket = "your-bucket-name"
    s3_key    = "pizza_order_handler.zip"
  }

  environment {
    variables = {
      PIZZA_STORE_API_KEY = "your-pizza-store-api-key"
    }
  }
}

resource "aws_lex_intent" "pizza_order_intent" {
  name           = "PizzaOrderIntent"
  description    = "Intent to order a pizza"
  child_directed = false

  sample_utterances = [
    "I would like to order a pizza",
    "Can you order a pizza for me?",
    "I need a pizza",
  ]

  slot {
    name        = "PizzaSize"
    slot_type   = "PizzaSizes"
    description = "Size of the pizza"
    slot_constraint = "Required"
    sample_utterances = [
      "I would like a {PizzaSize} pizza",
    ]
  }

  slot {
    name        = "Quantity"
    slot_type   = "Quantity"
    description = "Number of pizzas"
    slot_constraint = "Required"
    sample_utterances = [
      "I would like {Quantity} {PizzaSize} pizzas",
    ]
  }

  slot {
    name        = "PizzaType"
    slot_type   = "PizzaTypes"
    description = "Type of pizza"
    slot_constraint = "Required"
    sample_utterances = [
      "I would like a {PizzaType} pizza",
    ]
  }

  fulfillment_activity {
    type = "CodeHook"

    code_hook {
      message_version = "2.0"
      uri            = aws_lambda_function.pizza_order_handler.invoke_arn
    }
  }
}

resource "aws_lex_bot" "pizza_order_bot" {
  name             = "PizzaOrderBot"
  description     = "Bot to order pizzas"
  child_directed   = false
  idle_session_ttl_in_seconds = 600
  locale           = "en-US"
  process_behavior = "BUILD"

  intent {
    intent_name    = pizza_order_intent.name
    intent_version = "1"
  }

  abort_statement {
    message {
      content      = "Sorry, I couldn't understand your request. Please try again."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand you. Could you please rephrase your request?"
      content_type = "PlainText"
    }
  }
}
