provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "my_vpc" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = "my_vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id          = aws_vpc.my_vpc.id
  cidr_block      = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private_subnet_app" {
  vpc_id          = aws_vpc.my_vpc.id
  cidr_block      = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "private_subnet_app"
  }
}

resource "aws_subnet" "private_subnet_db" {
  vpc_id          = aws_vpc.my_vpc.id
  cidr_block      = "10.0.3.0/24"
  availability_zone = "us-east-1c"

  tags = {
    Name = "private_subnet_db"
  }
}

resource "aws_security_group" "public_sg" {
  vpc_id = aws_vpc.my_vpc.id
  description = "Allow HTTP and HTTPS traffic from anywhere"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "public_sg"
  }
}

resource "aws_security_group" "app_sg" {
  vpc_id = aws_vpc.my_vpc.id
  description = "Allow SSH and HTTP traffic from the public subnet"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.public_subnet.cidr_block]
  }
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.public_subnet.cidr_block]
  }
  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  vpc_id = aws_vpc.my_vpc.id
  description = "Allow inbound traffic from the application subnet"
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.private_subnet_app.cidr_block]
  }
  tags = {
    Name = "db_sg"
  }
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI for Ubuntu
  instance_type = "t3.micro"
  subnet_id      = aws_subnet.public_subnet.id
  security_groups = [aws_security_group.public_sg.id]

  tags = {
    Name = "web_server"
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI for Ubuntu
  instance_type = "t3.micro"
  subnet_id      = aws_subnet.private_subnet_app.id
  security_groups = [aws_security_group.app_sg.id]

  tags = {
    Name = "app_server"
  }
}

resource "aws_db_instance" "database" {
  engine         = "mysql"
  engine_version = "5.7"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  db_subnet_group_name = aws_subnet.private_subnet_db.id
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  username = "admin"
  password = "password123"
  skip_final_snapshot = true

  tags = {
    Name = "database"
  }
}
