provider "aws" {
  region = "us-east-1"
}

resource "aws_redshift_cluster" "primary_cluster" {
  cluster_identifier = "primary-cluster"
  node_type         = "dc1.large"
  master_username   = "admin"
  master_password   = "SecurePassword123!"
  cluster_type       = "single-node"
  availability_zone = "us-east-1a"

  # Enable event subscription
  event_subscription_name = "primary-cluster-events"
  sns_topic_arn           = aws_sns_topic.primary_cluster.arn

  # Enable logging
  logging {
    enable     = true
    bucket_name = "my-redshift-logs-bucket"
    log_destination_type = "cloudwatch"
    log_exports = ["querylog", "slowquery"]
  }

  # Snapshot copy to us-east-2
  snapshot_copy {
    destination_region = "us-east-2"
  }
}

resource "aws_redshift_cluster" "secondary_cluster" {
  cluster_identifier = "secondary-cluster"
  node_type         = "dc1.large"
  master_username   = "admin"
  master_password   = "SecurePassword123!"
  cluster_type       = "single-node"
  availability_zone = "us-east-2a"

  # Enable event subscription
  event_subscription_name = "secondary-cluster-events"
  sns_topic_arn           = aws_sns_topic.secondary_cluster.arn

  # Enable logging
  logging {
    enable     = true
    bucket_name = "my-redshift-logs-bucket"
    log_destination_type = "cloudwatch"
    log_exports = ["querylog", "slowquery"]
  }

  # Snapshot copy to us-east-1
  snapshot_copy {
    destination_region = "us-east-1"
  }
}

resource "aws_sns_topic" "primary_cluster" {
  name = "primary-cluster-events"
}

resource "aws_sns_topic" "secondary_cluster" {
  name = "secondary-cluster-events"
}
