```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "sagemaker_model_bucket" {
  bucket = "my-sagemaker-model-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name = "SageMaker Model Bucket"
  }
}

resource "aws_iam_role" "sagemaker_model_execution_role" {
  name_prefix = "sagemaker-execution-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "SageMaker Model Execution Role"
  }
}

resource "aws_sagemaker_model" "sagemaker_model" {
  name               = "my-sagemaker-model"
  execution_role_arn = aws_iam_role.sagemaker_model_execution_role.arn

  primary_container {
    image = "amazon/sagemaker-scikit-learn:latest"
    model_data_url = "s3://${aws_s3_bucket.sagemaker_model_bucket.bucket}/model.tar.gz"
  }

  tags = {
    Name = "SageMaker Model"
  }
}

resource "aws_sagemaker_endpoint_configuration" "sagemaker_endpoint_config" {
  name = "my-sagemaker-endpoint-config"

  production_variants {
    variant_name           = "variant-1"
    model_name             = aws_sagemaker_model.sagemaker_model.name
    initial_instance_count = 1
    instance_type          = "ml.t2.micro"
  }

  data_capture_config {
    destination_s3_uri = "s3://${aws_sagemaker_model_bucket.sagemaker_model_bucket.bucket}/capture-data"
    initial_sampling_percentage = 100
  }

  tags = {
    Name = "SageMaker Endpoint Configuration"
  }
}

resource "aws_sagemaker_endpoint" "sagemaker_endpoint" {
  name                 = "my-sagemaker-endpoint"
  endpoint_config_name = aws_sagemaker_endpoint_configuration.sagemaker_endpoint_config.name

  tags = {
    Name = "SageMaker Endpoint"
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

This Terraform program creates a SageMaker endpoint configuration for a SageMaker model, including an S3 bucket for storing the model artifacts, an IAM role for executing the model, and a SageMaker model itself. The endpoint is then deployed using the endpoint configuration.

