    client_subnets = [aws_subnet.my_subnet.id]
    security_groups = [aws_security_group.my_security_group.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.my_kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.my_cloudwatch_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.my_kinesis_firehose_delivery_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.my_s3_bucket.name
        prefix  = "logs/msk/"
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

resource "aws_kms_key" "my_kms_key" {
  description = "My KMS Key"
}

resource "aws_cloudwatch_log_group" "my_cloudwatch_log_group" {
  name = "my-msk-cluster-logs"
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-msk-cluster-logs-bucket"
}

resource "aws_kinesis_firehose_delivery_stream" "my_kinesis_firehose_delivery_stream" {
  name        = "my-msk-cluster-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.my_iam_role.arn
    bucket_arn = aws_s3_bucket.my_s3_bucket.arn
  }

  tags = {
    LogDeliveryEnabled = "true"
  }
}
