resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket-${random_string.random_suffix.result}"

  tags = {
    Name = "Example S3 Bucket"
  }
}

resource "aws_s3_bucket_request_payment_configuration" "example_payment_config" {
  bucket = aws_s3_bucket.example_bucket.bucket
  payer  = "Requester"

  expected_bucket_owner = "123456789012" # Replace with your actual AWS account ID
}

resource "aws_s3_bucket_ownership_controls" "example_ownership_controls" {
