  vpc_id = aws_vpc.cs_class_vpc.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "cs_class_subnet2" {
  vpc_id = aws_vpc.cs_class_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "cs_class_sg" {
  vpc_id = aws_vpc.cs_class_vpc.id
  description = "Allow inbound HTTP and HTTPS traffic"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol   = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol   = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name = "cs_class_autograder"
  service_role = aws_iam_role.cs_class_autograder_role.arn
  vpc_config {
    vpc_id = aws_vpc.cs_class_vpc.id
    subnets = [aws_subnet.cs_class_subnet1.id, aws_subnet.cs_class_subnet2.id]
    security_group_ids = [aws_security_group.cs_class_sg.id]
  }
