    type = "NO_ARTIFACTS"
  }
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }
  logs_config {
    cloudwatch_logs {
      group_name  = "cs_class_autograder_logs"
      stream_name = "cs_class_autograder_stream"
    }
    s3_logs {
      status   = "ENABLED"
      location = "cs_class_autograder_logs/build-log"
    }
  }
  source {
    type = "GITHUB"
    location = "https://github.com/example/cs-class-autograder.git"
    git_clone_depth = 1
  }
}
