provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = "cs-class-autograder-results-${var.student_id}"
  acl    = "private"
}

resource "aws_codebuild_project" "autograder_project" {
  name          = "cs-class-autograder-${var.student_id}"
  description   = "Runs students' code and stores the results in S3."
  service_role  = aws_iam_role.autograder_role.arn
  build_timeout = 60

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.autograder_results.bucket
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "STUDENT_ID"
      value = var.student_id
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "cs-class-autograder-logs-${var.student_id}"
      stream_name = "build-${var.student_id}"
    }

    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.autograder_results.bucket}/build-log"
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_username}/${var.github_repo}.git"
    git_clone_depth = 1
  }

  source_version = "main"

  vpc_config {
    vpc_id = aws_vpc.autograder_vpc.id
    subnets = [
      aws_subnet.autograder_subnet_1.id,
      aws_subnet.autograder_subnet_2.id,
    ]
    security_group_ids = [
      aws_security_group.autograder_sg.id,
    ]
  }

  tags = {
    Class = "CS",
    StudentID = var.student_id,
    Repository = "${var.github_username}/${var.github_repo}",
  }
}

resource "aws_iam_role" "autograder_role" {
  name               = "cs-class-autograder-role-${var.student_id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Principal = {
          Service = "codebuild.amazonaws.com",
        },
        Action = "sts:AssumeRole",
      },
    ],
  })

  inline_policy {
    name = "autograder-s3-policy"
    policy = jsonencode({
      Version = "2012-10-17",
      Statement = [
        {
          Effect   = "Allow",
          Action   = ["s3:PutObject", "s3:GetObject"],
          Resource = ["arn:aws:s3:::${aws_s3_bucket.autograder_results.bucket}/*"],
        },
      ],
    }),
  }
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "autograder_subnet_1" {
  vpc_id     = aws_vpc.autograder_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "autograder_subnet_2" {
  vpc_id     = aws_vpc.autograder_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "autograder_sg" {
  name        = "cs-class-autograder-sg-${var.student_id}"
  description = "Security group for the autograder."

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

variable "student_id" {
  description = "The student ID for the autograder."
  default     = "student123"
}

variable "github_username" {
  description = "The GitHub username of the student."
  default     = "student_user"
}

variable "github_repo" {
  description = "The GitHub repository of the student's code."
