provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "cat_pictures" {
  name           = "cat_pictures_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "picture_id"
  range_key      = "upload_time"
  read_capacity  = 5
  write_capacity = 5
  attribute_definitions = [
    {
      attribute_name = "picture_id"
      attribute_type = "S"
    },
    {
      attribute_name = "upload_time"
      attribute_type = "N"
    }
  ]
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-1234567890"
  acl     = "private"
}

resource "aws_lambda_function" "cat_picture_upload" {
  function_name = "cat_picture_upload"
  role          = aws_iam_role.cat_picture_upload.arn
  handler       = "cat_picture_upload.lambda_handler"
  runtime       = "python3.8"
  timeout       = 30
  memory_size    = 128

  environment {
    variables = {
      TABLE_NAME = aws_dynamodb_table.cat_pictures.name
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  code {
    s3_bucket = aws_s3_bucket.cat_pictures_bucket.bucket
    s3_key    = "cat_picture_upload.py"
  }

  depends_on = [aws_iam_role.cat_picture_upload]
}

resource "aws_lambda_permission" "cat_picture_upload_permission" {
  statement_id  = "AllowInvokeFunction"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cat_picture_upload.function_name
  principal     = "apigateway.amazonaws.com"
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name = "cat_picture_api"
}

resource "aws_api_gateway_resource" "cat_picture_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "cat-pictures"
}

resource "aws_api_gateway_method" "cat_picture_method" {
  rest_api_id            = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id             = aws_api_gateway_resource.cat_picture_resource.id
  http_method            = "POST"
  authorization         = "NONE"
  request_parameters    = {
    "method.request.path.picture_id" = "required"
  }
  request_models        = {
    "application/json" = "CatPictureInput"
  }
  request_validator_id = aws_api_gateway_request_validator.cat_picture_request_validator.id

  depends_on = [aws_api_gateway_resource.cat_picture_resource]
}

resource "aws_api_gateway_request_validator" "cat_picture_request_validator" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  name        = "cat_picture_request_validator"
  validate_request_body = true
  validate_request_parameters = true
}

resource "aws_iam_role" "cat_picture_upload" {
