    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  policies = [
    jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "dynamodb:GetItem",
            "dynamodb:PutItem",
            "dynamodb:UpdateItem",
            "dynamodb:DeleteItem",
            "s3:GetObject",
            "s3:PutObject",
            "s3:DeleteObject"
          ]
          Effect = "Allow"
          Resource = [
            "${aws_dynamodb_table.cat_pictures.arn}",
            "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
          ]
        }
      ]
    })
  ]
}
