provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Lambda execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach necessary policies to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Create an S3 bucket to store Lambda code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "my-lambda-code-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name = "My Lambda Code Bucket"
  }
}

# Upload Lambda code to the S3 bucket
resource "aws_s3_object" "lambda_code" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda_function.zip"
  source = "./path/to/your/lambda_function.zip"
}

# Create a Lambda function
resource "aws_lambda_function" "code_runner" {
  function_name = "daily_code_runner"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  timeout       = 30

  code {
    s3_bucket = aws_s3_bucket.lambda_code_bucket.bucket
    s3_key    = aws_s3_object.lambda_code.key
  }

  environment {
    variables = {
      RUN_AT = "07:00:00"
    }
  }
}

# Create an EventBridge rule to trigger the Lambda function daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_code_run" {
  name        = "daily_code_run"
  schedule_expression = "cron(0 7 * * ? *)"
  description = "Runs the daily code at 7 UTC"

  targets {
    arn = aws_lambda_function.code_runner.arn
  }
}
```

