provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for Lambda execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# Create an SNS topic for notifications
resource "aws_sns_topic" "notifications" {
  name = "lambda_notifications"
}

# Create an SNS topic policy to allow Lambda to publish messages
resource "aws_sns_topic_policy" "notifications_policy" {
  arn = aws_sns_topic.notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "SNS:Publish"
        Resource = aws_sns_topic.notifications.arn
      },
    ]
  })
}

# Create a Lambda function to handle the task
resource "aws_lambda_function" "daily_task" {
  function_name = "daily_task"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  code = filebase64sha256("path/to/daily_task.py")

  environment = {
    variables = {
      TIME_ZONE = "UTC"
    }
  }

  timeout = 30

  vpc_config = {
    subnet_ids = ["subnet-12345678", "subnet-23456789"]
    security_group_ids = ["sg-12345678"]
  }

  tags = {
    Name = "daily_task"
  }
}

# Create a Lambda alias for version control
resource "aws_lambda_alias" "daily_task_alias" {
  name             = "daily_task_alias"
  description      = "Alias for the latest version of the Lambda function"
  function_name    = aws_lambda_function.daily_task.function_name
  function_version = "$LATEST"
}

# Create an EventBridge rule to trigger the Lambda function daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_trigger" {
  name        = "daily_trigger"
  description = "Trigger the daily_task Lambda function daily at 7 UTC"
  schedule_expression = "cron(0 7 * * ? *)"

  depends_on = [aws_lambda_function.daily_task]
}

# Create an EventBridge target to invoke the Lambda function
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_trigger.name
  target_id = "LambdaTarget"
  arn       = aws_lambda_function.daily_task.invoke_arn
}

# Create a CloudWatch log group for logging
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/daily_task"
}

# Create an API Gateway REST API to trigger the Lambda function
resource "aws_api_gateway_rest_api" "api_gateway" {
  name = "daily_task_api"
}

# Create an API Gateway method to invoke the Lambda function
resource "aws_api_gateway_method" "lambda_method" {
  rest_api_id = aws_api_gateway_rest_api.api_gateway.id
  resource_id = aws_api_gateway_rest_api.api_gateway.root_resource_id
  http_method = "POST"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri = "arn:aws:apigateway:${var.region}:lambda:path/2015-03-31/functions/${aws_lambda_function.daily_task.invoke_arn}/invocations"
    integration_http_method = "POST"
  }
}

# Create an API Gateway deployment to make the API available
resource "aws_api_gateway_deployment" "api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.api_gateway.id
  stage_name = "prod"
}

# Create an API Gateway stage to make the API available
resource "aws_api_gateway_stage" "api_stage" {
  rest_api_id = aws_api_gateway_rest_api.api_gateway.id
  stage_name = "prod"
  deployment_id = aws_api_gateway_deployment.api_deployment.id
}

# Create a Lambda permission to allow API Gateway to invoke the Lambda function
resource "aws_lambda_permission" "api_gateway_permission" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "arn:aws:execute-api:${var.region}:${var.account_id}:${aws_api_gateway_rest_api.api_gateway.id}/*/*"
}

# Create a Lambda permission to allow SNS to publish messages
resource "aws_lambda_permission" "sns_permission" {
  statement_id  = "AllowSNSPublish"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task.function_name
  principal     = "sns.amazonaws.com"
  source_arn    = aws_sns_topic.notifications.arn
}
