    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_lambda_function" "lambda_func" {
  function_name = "cron_daily_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = "my-lambda-bucket"
  s3_key        = "lambda_func.zip"

  environment {
    variables = {
      CRON_EXPRESSION = "cron(0 7 * * ? *)"
    }
  }
}

resource "aws_lambda_permission" "lambda_permission" {
  statement_id  = "AllowCloudWatchEvents"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lambda_func.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron_daily.arn
}

resource "aws_cloudwatch_event_rule" "cron_daily" {
  name        = "cron_daily"
  schedule_expression = "cron(0 7 * * ? *)"
  description = "EventBridge rule to trigger daily at 7 UTC"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.cron_daily.name
  target_id = "LambdaTarget"
  arn       = aws_lambda_function.lambda_func.arn
}
