  }
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  description = "Allow inbound HTTP and HTTPS traffic"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "Video Streaming Security Group"
  }
}

resource "aws_instance" "video_streaming_instance" {
  ami           = "ami-005e54dee72cc1d00" # us-east-1
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.id]
  tags = {
    Name = "Video Streaming Instance"
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.video_streaming_sg.id]
  subnets            = [aws_subnet.video_streaming_subnet.id]

  access_logs {
    bucket  = "video-streaming-access-logs"
    prefix  = "logs"
    enabled = true
  }

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  listener {
    instance_port      = 80
    instance_protocol  = "http"
    lb_port            = 443
    lb_protocol        = "https"
    ssl_certificate_id = "arn:aws:iam::123456789012:server-certificate/certName"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    target              = "HTTP:80/"
    interval            = 30
  }

  instances                   = [aws_instance.video_streaming_instance.id]
  cross_zone_load_balancing   = true
  idle_timeout                = 400
  connection_draining         = true
  connection_draining_timeout = 400

  tags = {
    Name = "Video Streaming Load Balancer"
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  stickiness {
    type = "lb_cookie"
    cookie_duration = 3600
  }

  target_failover {
    on_deregistration = "rebalance"
    on_unhealthy      = "rebalance"
  }

  target_health_state {
    enable_unhealthy_connection_termination = true
  }
}

resource "aws_kinesis_video_stream" "video_streaming_stream" {
  name                    = "video-streaming-stream"
  data_retention_in_hours = 1
  device_name             = "video-streaming-device"
  media_type              = "video/h264"

  tags = {
    Name = "Video Streaming Kinesis Video Stream"
  }
}
