  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ec2_instance" "video_streaming_instance" {
  ami           = data.aws_ami.amazon_linux.id
  instance_type = var.instance_type
  key_name      = "my-key-pair"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.id]
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.video_streaming_sg.id]
  subnets            = [aws_subnet.video_streaming_subnet.id]

  access_logs {
    bucket  = "my-lb-access-logs"
    prefix  = "video-streaming-lb"
    enabled = true
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    enabled     = true
    healthy_threshold = 2
    interval       = 30
    matcher        = "200"
    path           = "/"
    port           = 80
    protocol       = "HTTP"
    timeout        = 10
    unhealthy_threshold = 2
  }

  stickiness {
    type = "lb_cookie"
    cookie_duration = 86400
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "example.com"
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "video-streaming.example.com"
  type    = "A"
  ttl     = 300
  records = [aws_subnet.video_streaming_subnet.primary_network_acl_id]
}
