}

resource "aws_kms_key" "postgres-kms-key" {
  description = "KMS key for PostgreSQL encryption"
  key_usage   = "ENCRYPT_DECRYPT"
}

resource "aws_db_parameter_group" "postgres-custom-param-group" {
  family = "postgres13"

  parameter {
    name        = "max_connections"
    value       = "100"
    apply_method = "immediate"
  }

  parameter {
    name        = "work_mem"
    value       = "2MB"
    apply_method = "immediate"
  }
}

resource "aws_db_subnet_group" "postgres-subnet-group" {
  name        = "postgres-subnet-group"
  description = "Subnet group for PostgreSQL instances"
  subnet_ids = [
    "subnet-12345678",  # Replace with actual subnet IDs
    "subnet-87654321",  # Replace with actual subnet IDs
  ]
}

resource "aws_security_group" "postgres-security-group" {
  name        = "postgres-security-group"
  description = "Security group for PostgreSQL instances"

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol    = "-1"
    from_port   = 0
    to_port     = 65535
  }

  egress {
    cidr_blocks = ["0.0.0.0/0"]
    protocol    = "-1"
    from_port   = 0
    to_port     = 65535
  }
}

resource "aws_db_instance" "postgres-db-instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "postgres"
  engine_version = "13.6"
  db_subnet_group_name = aws_db_subnet_group.postgres-subnet-group.name
  security_group_ids = [aws_security_group.postgres-security-group.id]
  parameter_group_name = aws_db_parameter_group.postgres-custom-param_group.name
  kms_key_id = aws_kms_key.postgres-kms-key.arn
  multi_az = true
  storage_encrypted = true
  final_snapshot_identifier = "pgsnapshot"
}

resource "aws_db_snapshot" "postgres-db-snapshot" {
  db_instance_identifier = aws_db_instance.postgres-db-instance.identifier
  db_snapshot_identifier = "pgsnapshot-$(date +%Y%m%d%H%M%S)"
}
