  vpc_id          = aws_vpc.airbyte_vpc.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "airbyte_subnet_2" {
  vpc_id          = aws_vpc.airbyte_vpc.id
  cidr_block       = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_security_group" "airbyte_sg" {
  name        = "airbyte-sg"
  description = "Allow inbound traffic to PostgreSQL"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "airbyte_role" {
  name = "airbyte-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_db_subnet_group" "airbyte_subnet_group" {
  name       = "airbyte-subnet-group"
  subnet_ids = [aws_subnet.airbyte_subnet_1.id, aws_subnet.airbyte_subnet_2.id]
}

resource "aws_rds_cluster" "airbyte_test_cluster" {
  engine              = "aurora-postgresql"
  engine_version      = "15.2"
  db_subnet_group_name = aws_db_subnet_group.airbyte_subnet_group.name
  vpc_security_group_ids = [aws_security_group.airbyte_sg.id]
  iam_roles           = [aws_iam_role.airbyte_role.arn]
}

resource "aws_db_instance" "airbyte_test_instance" {
  engine              = "aurora-postgresql"
  engine_version      = "15.2"
  instance_class      = "db.t3.micro"
  db_subnet_group_name = aws_db_subnet_group.airbyte_subnet_group.name
  vpc_security_group_ids = [aws_security_group.airbyte_sg.id]
  iam_roles           = [aws_iam_role.airbyte_role.arn]
}
