  name_prefix = "airbyte-launch-template"
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_role.airbyte_instance_profile.arn
  network_interfaces {
    device_index = 0
    subnet_id = aws_subnet.airbyte_test_subnet_1.id
    associate_public_ip_address = true
  }

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_size = 50
      encrypted = true
    }
  }

  tags = {
    Name = "Airbyte-Launch-Template"
  }
}

resource "aws_iam_role" "airbyte_instance_profile" {
  name = "airbyte-instance-profile"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
