  storage_encrypted = true
  storage_throughput = 100
  db_subnet_group_name = aws_db_subnet_group.example_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.example_sg.id]
  tags = {
    Name = "example-db-instance"
  }
}

resource "aws_db_proxy" "example_db_proxy" {
  engine_family = "POSTGRESQL"
  name = "example-proxy"
  role_arn = aws_iam_role.example_role.arn
  vpc_subnet_ids = [aws_subnet.example_subnet.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Proxy authentication"
    secret_arn = aws_secretsmanager_secret.example.arn
  }

  tags = {
    Name = "example-db-proxy"
  }
}

