  rule {
    rule_name         = "maintenance-rule"
    target_vault_name = aws_backup_vault.mysql_backup_vault.name
    schedule          = "cron(0 17 * * ? *)"
    start_window       = "17:00"
    end_window        = "17:30"
    recurrence_window = "1 day"
  }
}

