}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count           = 2
  cidr_block       = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  vpc_id          = aws_vpc.main.id
}

resource "aws_subnet" "private" {
  count           = 2
  cidr_block       = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index + 2]
  vpc_id          = aws_vpc.main.id
}

resource "aws_lb" "my-load-balancer" {
  name               = "my-load-balancer"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.my-security-group.id]
  load_balancer_type = "application"

  access_logs {
    bucket = "my-access-logs-bucket"
    enabled = true
    prefix = "load-balancer-logs/"
  }

  connection_logs {
    bucket = "my-connection-logs-bucket"
    enabled = true
    prefix = "load-balancer-connections/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_security_group" "my-security-group" {
  name        = "my-security-group"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "my-target-group" {
  name               = "my-target-group"
  port                = 80
  protocol            = "HTTP"
  vpc_id              = aws_vpc.main.id
  target_type         = "instance"
  health_check {
    enabled     = true
    healthy_threshold = 2
    interval      = 30
    path           = "/"
    port           = 80
    protocol       = "HTTP"
    timeout        = 10
    unhealthy_threshold = 2
  }
}

resource "aws_lb_target_group_attachment" "my-target-group-attachment" {
  target_group_arn = aws_lb_target_group.my-target-group.arn
  target_id        = aws_instance.my-instance.id
}
