provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count          = 2
  cidr_block     = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  vpc_id         = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count          = 2
  cidr_block     = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  vpc_id         = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index + 2]
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups     = [aws_security_group.my_security_group.id]
  enable_http2       = true
  idle_timeout       = 60
  load_balancer_type = "application"

  access_logs {
    bucket = "my-load-balancer-access-logs"
    enabled = true
    prefix = "access-logs/"
  }

  connection_logs {
    bucket = "my-load-balancer-connection-logs"
    enabled = true
    prefix = "connection-logs/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_lb_target_group" "my_lambda_target_group" {
  name               = "my-lambda-target-group"
  port                = 80
  protocol            = "HTTP"
  protocol_version    = "HTTP1"
  vpc_id              = aws_vpc.main.id
  target_type         = "lambda"
  lambda_multi_value_headers_enabled = true
  load_balancing_algorithm_type = "round_robin"

  health_check {
    enabled   = true
    healthy_threshold = 2
    interval       = 30
    matcher       = "200"
    path          = "/"
    port          = "traffic-port"
    protocol      = "HTTP"
    timeout       = 10
    unhealthy_threshold = 2
  }

  stickiness {
    type = "lb_cookie"
    cookie_duration = 86400
    cookie_name = "my-cookie"
    enabled = true
  }

  target_group_health {
    dns_failover {
      minimum_healthy_targets_count = "1"
      minimum_healthy_targets_percentage = "50"
    }
    unhealthy_state_routing {
      minimum_healthy_targets_count = 1
      minimum_healthy_targets_percentage = "50"
    }
  }

  target_health_state {
    enable_unhealthy_connection_termination = true
    unhealthy_draining_interval = 300
  }
}

resource "aws_security_group" "my_security_group" {
  name        = "my-security-group"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
