  region = "us-east-1"
}

variable "vpc_cidr_block" {
  default = "192.168.0.0/16"
}

variable "custom_dns_servers" {
  default = ["8.8.8.8", "8.8.4.4"]
}

variable "google_dns_servers" {
  default = ["8.8.8.8", "8.8.4.4"]
}

